-- B-20: 30 günlük jo suburi programı metni (fact-check onaylı: 2026-11-05-30-gun-jo-programi.md).
-- Seed programı yalnız program tablosu boşken eklediği için prod satırını bu dosya günceller.
-- İdempotent (aynı değerleri yazar), silme yok, enrollments/enrollment_days'e dokunulmaz.
-- Çalıştırma (prod, İlteriş): docker compose exec -T db psql -U <kullanıcı> <db> < docs/team/content/verified/2026-11-05-30-gun-jo-programi.sql
BEGIN;

UPDATE programs
SET description_en = $e$One month of daily, structured jo suburi practice. Four weekly themes: thrusts, strikes, one-handed and hasso forms, and flowing forms. About 10–20 minutes a day.$e$,
    description_tr = $t$Bir ay boyunca her gün yapılandırılmış jo suburi çalışması. Dört haftalık tema: dürtüşler, vuruşlar, tek el ve hasso formları, akış formları. Günde yaklaşık 10–20 dakika.$t$
WHERE slug = '30-day-jo-suburi';
-- Beklenen: UPDATE 1

UPDATE program_days AS d
SET title_en = v.title_en, title_tr = v.title_tr, content_en = v.content_en, content_tr = v.content_tr
FROM (VALUES
  (1, $a$Focus: choku tsuki$a$, $b$Odak: choku tsuki$b$, $c$Week theme: Tsuki fundamentals. Warm up 5 minutes (wrists, shoulders, hips). Main work: choku tsuki — 3 sets of 20 repetitions, rest between sets. Last set slower than the first: precision over speed. If you haven't learned this movement from a teacher yet, ask yours first. Log your session when you're done.$c$, $d$Hafta teması: Tsuki temelleri. 5 dakika ısın (bilek, omuz, kalça). Ana çalışma: choku tsuki — 3 set x 20 tekrar, setler arası dinlen. Son set ilkinden yavaş: hızdan önce isabet. Bu hareketi henüz hocandan öğrenmediysen önce ona danış. Bitirince seansını kaydet.$d$),
